#!/usr/bin/env bash
set -euo pipefail
source "$(dirname -- "${BASH_SOURCE[0]}")/env.sh"
python3 - "$REPO_ROOT/.codebase-memory/environments/linux" <<'PY'
import datetime,json,os,pathlib,platform,shutil,subprocess,sys
p=pathlib.Path(sys.argv[1]);p.mkdir(parents=True,exist_ok=True)
def run(argv):
 try: return subprocess.run(argv,capture_output=True,text=True,timeout=15).stdout.strip()
 except (OSError,subprocess.TimeoutExpired): return 'unavailable'
def version(argv):
 try:
  r=subprocess.run(argv,capture_output=True,text=True,timeout=15);return (r.stdout+r.stderr).strip()[:1500]
 except (OSError,subprocess.TimeoutExpired): return 'unavailable'
tools={k:{'path':shutil.which(k),'version':version([k,*a])} for k,a in {'java':['-version'],'javac':['-version'],'git':['--version'],'bash':['--version'],'node':['--version'],'npm':['--version'],'adb':['version'],'emulator':['-version'],'sdkmanager':['--version']}.items()}
now=datetime.datetime.now(datetime.timezone.utc)
s={'platformId':'linux','collectedAt':now.isoformat(),'refreshDue':(now+datetime.timedelta(days=7)).isoformat(),'os':platform.system(),'distribution':run(['lsb_release','-ds']),'architecture':platform.machine(),'virtualization':run(['systemd-detect-virt']),'kvm':{'exists':pathlib.Path('/dev/kvm').exists(),'readWrite':os.access('/dev/kvm',os.R_OK|os.W_OK),'acceleration':version(['emulator','-accel-check']),'nested':next((q.read_text().strip() for q in [pathlib.Path('/sys/module/kvm_intel/parameters/nested'),pathlib.Path('/sys/module/kvm_amd/parameters/nested')] if q.exists()),None)},'androidHome':os.environ.get('ANDROID_HOME'),'javaHome':os.environ.get('JAVA_HOME'),'tools':tools,'avds':run(['emulator','-list-avds']),'devices':run(['adb','devices','-l']),'sdkPackages':[str(q.parent) for q in pathlib.Path(os.environ['ANDROID_HOME']).rglob('source.properties')],'cpuVirtualizationFlags':[f for f in ('vmx','svm') if f in pathlib.Path('/proc/cpuinfo').read_text().split()],'user':run(['id']),'memory':run(['free','-h']),'disk':run(['df','-h',os.environ['HOME']])}
(p/'environment-snapshot.json').write_text(json.dumps(s,indent=2)+'\n')
(p/'environment-snapshot.md').write_text('# Local Linux environment snapshot\n\nGenerated by `tools/android/snapshot.sh`; expires after seven days. Machine-local, ignored by Git.\n\n```json\n'+json.dumps(s,indent=2)+'\n```\n')
print('Local snapshot: '+str(p/'environment-snapshot.json'))
PY
